CREATE TABLE public.offsite_admins (user_id uuid PRIMARY KEY);
GRANT SELECT ON public.offsite_admins TO authenticated; GRANT ALL ON public.offsite_admins TO service_role;
ALTER TABLE public.offsite_admins ENABLE ROW LEVEL SECURITY;
CREATE POLICY propria ON public.offsite_admins FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.offsite_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM offsite_admins WHERE user_id=auth.uid()) $$;
CREATE FUNCTION public.offsite_cadeira() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT cadeira_id FROM mt_usuarios WHERE user_id=auth.uid() AND perfil='diretor' LIMIT 1 $$;
CREATE FUNCTION public.offsite_acesso() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('admin',offsite_admin(),'cadeira_id',offsite_cadeira(),'permitido',offsite_admin() OR offsite_cadeira() IS NOT NULL) $$;
CREATE TABLE public.offsite_config (id text PRIMARY KEY DEFAULT '2027', conteudo jsonb NOT NULL DEFAULT '{}', prazo date NOT NULL DEFAULT '2026-11-07', atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.offsite_config TO authenticated; GRANT ALL ON public.offsite_config TO service_role;
ALTER TABLE public.offsite_config ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.offsite_config FOR SELECT TO authenticated USING(offsite_admin() OR offsite_cadeira() IS NOT NULL);
CREATE POLICY administrar ON public.offsite_config FOR ALL TO authenticated USING(offsite_admin()) WITH CHECK(offsite_admin());
CREATE TABLE public.offsite_respostas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE NOT NULL, cadeira_id uuid NOT NULL, nome text NOT NULL DEFAULT '', respostas jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'rascunho', revisao integer NOT NULL DEFAULT 0, enviado_em timestamptz, atualizado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.offsite_respostas TO authenticated; GRANT ALL ON public.offsite_respostas TO service_role;
ALTER TABLE public.offsite_respostas ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.offsite_respostas FOR SELECT TO authenticated USING(offsite_admin() OR (user_id=auth.uid() AND cadeira_id=offsite_cadeira()));
CREATE TABLE public.offsite_historico (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resposta_id uuid REFERENCES offsite_respostas(id), ator uuid, acao text NOT NULL, antes jsonb, depois jsonb, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.offsite_historico TO authenticated; GRANT ALL ON public.offsite_historico TO service_role;
ALTER TABLE public.offsite_historico ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.offsite_historico FOR SELECT TO authenticated USING(offsite_admin());
CREATE TABLE public.offsite_materiais (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), titulo text NOT NULL, cadeira_id uuid, url text, arquivo_path text, criado_em timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.offsite_materiais TO authenticated; GRANT ALL ON public.offsite_materiais TO service_role;
ALTER TABLE public.offsite_materiais ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.offsite_materiais FOR SELECT TO authenticated USING(offsite_admin() OR (offsite_cadeira() IS NOT NULL AND (cadeira_id IS NULL OR cadeira_id=offsite_cadeira())));
CREATE POLICY administrar ON public.offsite_materiais FOR ALL TO authenticated USING(offsite_admin()) WITH CHECK(offsite_admin());
CREATE TABLE public.offsite_backlog (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), resposta_id uuid NOT NULL REFERENCES offsite_respostas(id), proposta_indice integer NOT NULL, proposta jsonb NOT NULL, status text NOT NULL DEFAULT 'Proposta pré-offsite', criado_por uuid, criado_em timestamptz NOT NULL DEFAULT now(), UNIQUE(resposta_id,proposta_indice));
GRANT SELECT ON public.offsite_backlog TO authenticated; GRANT ALL ON public.offsite_backlog TO service_role;
ALTER TABLE public.offsite_backlog ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.offsite_backlog FOR SELECT TO authenticated USING(offsite_admin());
CREATE FUNCTION public.offsite_salvar(_respostas jsonb,_revisao integer,_enviar boolean DEFAULT false) RETURNS public.offsite_respostas LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r offsite_respostas; c uuid; k text; BEGIN
c:=offsite_cadeira(); IF c IS NULL THEN RAISE EXCEPTION 'Conta sem cadeira de diretoria vinculada'; END IF;
IF jsonb_typeof(_respostas)<>'object' OR octet_length(_respostas::text)>1000000 THEN RAISE EXCEPTION 'Respostas inválidas'; END IF;
FOREACH k IN ARRAY ARRAY['1.1','1.2','2.1','4.3'] LOOP IF _respostas ? k AND (jsonb_typeof(_respostas->k)<>'array' OR jsonb_array_length(_respostas->k)>3) THEN RAISE EXCEPTION 'Limite de três itens'; END IF; END LOOP;
IF jsonb_array_length(coalesce(_respostas->'3.selecionadas','[]'))>3 OR jsonb_array_length(coalesce(_respostas->'4.1','[]'))>2 THEN RAISE EXCEPTION 'Seleção excede o limite'; END IF;
INSERT INTO offsite_respostas(user_id,cadeira_id,nome) SELECT auth.uid(),c,coalesce(p.display_name,'Diretor') FROM profiles p WHERE p.user_id=auth.uid() ON CONFLICT(user_id) DO NOTHING;
SELECT * INTO r FROM offsite_respostas WHERE user_id=auth.uid() FOR UPDATE;
IF r.id IS NULL THEN RAISE EXCEPTION 'Perfil não encontrado'; END IF;
IF r.status='enviado' THEN RAISE EXCEPTION 'Resposta enviada, solicite reabertura'; END IF;
IF r.revisao<>_revisao THEN RAISE EXCEPTION 'Resposta alterada em outra sessão. Recarregue antes de editar'; END IF;
UPDATE offsite_respostas SET respostas=_respostas,revisao=revisao+1,status=CASE WHEN _enviar THEN 'enviado' ELSE 'rascunho' END,enviado_em=CASE WHEN _enviar THEN now() ELSE enviado_em END,atualizado_em=now() WHERE id=r.id RETURNING * INTO r;
IF _enviar THEN INSERT INTO offsite_historico(resposta_id,ator,acao,depois) VALUES(r.id,auth.uid(),'enviar',to_jsonb(r)); END IF; RETURN r; END $$;
CREATE FUNCTION public.offsite_reabrir(_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r offsite_respostas; BEGIN IF NOT offsite_admin() THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO r FROM offsite_respostas WHERE id=_id FOR UPDATE; UPDATE offsite_respostas SET status='rascunho',revisao=revisao+1,atualizado_em=now() WHERE id=_id; INSERT INTO offsite_historico(resposta_id,ator,acao,antes) VALUES(_id,auth.uid(),'reabrir',to_jsonb(r)); END $$;
CREATE FUNCTION public.offsite_promover(_id uuid,_indice integer) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r offsite_respostas; v uuid; p jsonb; BEGIN IF NOT offsite_admin() THEN RAISE EXCEPTION 'Sem permissão'; END IF; SELECT * INTO r FROM offsite_respostas WHERE id=_id FOR UPDATE; p:=r.respostas->'4.3'->_indice; IF p IS NULL OR coalesce(p->>'nome','')='' THEN RAISE EXCEPTION 'Proposta sem nome'; END IF; INSERT INTO offsite_backlog(resposta_id,proposta_indice,proposta,criado_por) VALUES(_id,_indice,p,auth.uid()) ON CONFLICT(resposta_id,proposta_indice) DO NOTHING; SELECT id INTO v FROM offsite_backlog WHERE resposta_id=_id AND proposta_indice=_indice; RETURN v; END $$;
REVOKE ALL ON FUNCTION public.offsite_admin(),public.offsite_cadeira(),public.offsite_acesso(),public.offsite_salvar(jsonb,integer,boolean),public.offsite_reabrir(uuid),public.offsite_promover(uuid,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.offsite_admin(),public.offsite_cadeira(),public.offsite_acesso(),public.offsite_salvar(jsonb,integer,boolean),public.offsite_reabrir(uuid),public.offsite_promover(uuid,integer) TO authenticated;